#!/bin/sh
# Syncs the Rust core into the R package (src/rust/tsorder-core) so the
# package tarball is self-contained (CRAN builds offline). The copy carries
# a resolved Cargo.toml (no workspace inheritance, no dev-dependencies) and
# only the library sources. Run from bindings/r; CI checks the copy is
# current with `git diff --exit-code`.
set -e
dir="$(cd "$(dirname "$0")/.." && pwd)"
core="$dir/../../crates/tsorder-core"
dest="$dir/src/rust/tsorder-core"
rm -rf "$dest"
mkdir -p "$dest"
cp -R "$core/src" "$dest/src"
cat > "$dest/Cargo.toml" << 'TOML'
# Generated by tools/sync-core.sh from crates/tsorder-core - do not edit.
[package]
name = "tsorder-core"
version = "0.1.0"
edition = "2021"
rust-version = "1.81"
license = "MIT"
description = "Order selection for time-series models (vendored copy for the R package)"
publish = false

[features]
sim = []
ensemble = []

[dependencies]
TOML
echo "synced $(ls "$dest/src" | wc -l | tr -d ' ') source files"
